#!/usr/bin/env python3
import csv
import sys
from collections import defaultdict
from datetime import datetime

def validate_row(row, row_num):
    """Validate a transaction row. Returns (valid, error_msg)."""
    required = {'customer_id', 'amount', 'date'}
    if not all(k in row for k in required):
        return False, f"Missing required fields: {required - set(row.keys())}"

    if not row['customer_id'].strip():
        return False, "Empty customer_id"

    try:
        amount = float(row['amount'])
        if amount < 0:
            return False, "Negative amount"
    except (ValueError, TypeError):
        return False, f"Invalid amount: {row['amount']}"

    try:
        datetime.strptime(row['date'], '%Y-%m-%d')
    except ValueError:
        return False, f"Invalid date format (expected YYYY-MM-DD): {row['date']}"

    return True, None

def process_transactions(input_file, output_file):
    """Read transactions, validate, aggregate, write report."""
    totals = defaultdict(float)
    valid_count = 0
    error_count = 0
    errors = []

    try:
        with open(input_file, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            if not reader.fieldnames:
                print(f"Error: {input_file} is empty or invalid", file=sys.stderr)
                return

            for row_num, row in enumerate(reader, start=2):  # start=2 (1-indexed header)
                valid, error = validate_row(row, row_num)

                if valid:
                    customer_id = row['customer_id'].strip()
                    amount = float(row['amount'])
                    totals[customer_id] += amount
                    valid_count += 1
                else:
                    error_count += 1
                    errors.append(f"Row {row_num}: {error}")
                    if len(errors) <= 10:  # Log first 10 errors in detail
                        print(f"Row {row_num}: {error}", file=sys.stderr)

    except IOError as e:
        print(f"Error reading {input_file}: {e}", file=sys.stderr)
        return

    # Write report
    try:
        with open(output_file, 'w', encoding='utf-8') as f:
            f.write("Customer Transaction Report\n")
            f.write(f"Generated: {datetime.now().isoformat()}\n")
            f.write(f"Valid rows: {valid_count}, Errors: {error_count}\n")
            f.write("\n" + "=" * 50 + "\n")
            f.write(f"{'Customer ID':<20} {'Total':<15}\n")
            f.write("-" * 35 + "\n")

            for customer_id in sorted(totals.keys()):
                f.write(f"{customer_id:<20} ${totals[customer_id]:>13.2f}\n")

            f.write("-" * 35 + "\n")
            f.write(f"{'GRAND TOTAL':<20} ${sum(totals.values()):>13.2f}\n")

            if error_count > 0:
                f.write(f"\n{error_count} rows skipped due to validation errors.\n")
                if len(errors) > 10:
                    f.write(f"(First 10 errors shown in stderr; {len(errors) - 10} more)\n")

    except IOError as e:
        print(f"Error writing {output_file}: {e}", file=sys.stderr)
        return

    print(f"Report written to {output_file}")
    print(f"Processed {valid_count} valid transactions, {error_count} errors")

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <input_csv> <output_report>", file=sys.stderr)
        sys.exit(1)

    process_transactions(sys.argv[1], sys.argv[2])
